"""Données de seed pour les contenus et quiz de chaque module.

Chaque module a :
- 3 contenus (1 markdown + 1 vidéo + 1 ressource externe)
- 1 quiz avec 15-20 questions × 4 choix

Les vidéos ont une URL placeholder à remplacer via l'admin Django.
"""

MODULE_DATA = {}


def _q(title, explanation, choices):
    """Helper pour créer une question."""
    return {"title": title, "explanation": explanation, "choices": choices}


def _c(text, is_correct):
    """Helper pour créer un choix."""
    return {"text": text, "is_correct": is_correct}


